FILE = "caf-awards-2026-final-five.html"
TITLE = "Five Players, Two Countries: The Race for African Player of the Year"
TAG = "Flavor Sports"
H1 = "Five Players, Two Countries: The Race for African Player of the Year"
DEK = "Morocco and Senegal share all five places on the shortlist for CAF's biggest individual award. The winner is named in Lagos on Wednesday, 2 December."
META = "Flavor Sports · 27 Nov 2026 · 4 min read"
LEAD = ("img/sp-caf-awards-trophy.jpg", "The CAF African Player of the Year trophy", "wiwsport / Instagram")

BODY = [
("p", "CAF published its final shortlists for the 2026 awards on Wednesday, 25 November, and the race for African Player of the Year looks a lot like January's Africa Cup of Nations final. Three of the five finalists play for Morocco: Achraf Hakimi, Brahim Díaz and Ismael Saibari. The other two, Sadio Mané and Pape Gueye, play for Senegal."),
("p", "The list started with ten names when CAF announced its nominees on 4 November. Amad Diallo, Yoane Wissa, Antoine Semenyo, Ismaila Sarr and Teboho Mokoena didn't make the final five, although Mokoena is still in the running for Interclub Player of the Year."),
("h2", "", "Achraf Hakimi: ", "the holder"),
("p", "The Paris Saint-Germain defender won the award last November, and he's back to defend it. Morocco's year also took in a World Cup quarter-final, which France won 2-0 in Boston on 9 July."),
("h2", "", "Brahim Díaz: ", "the Golden Boot"),
("p", "The Real Madrid forward finished as top scorer at AFCON 2025, which Morocco hosted, and won the Golden Boot. His tournament ended in the hardest way. In the final in Rabat on 18 January, with the score at 0-0, Morocco were given a late penalty after a VAR review of a challenge on Díaz. He took it and didn't score, and Senegal went on to win 1-0 in extra time."),
("h2", "", "Ismael Saibari: ", "the breakout summer"),
("p", "Saibari scored in all three of Morocco's group games at the World Cup, starting with the opener against Brazil. Morocco then knocked out the Netherlands before losing to France in the last eight. On 1 July, Bayern Munich confirmed they had signed him from PSV Eindhoven on a deal running to 2031, with the fee reported at around €50 million."),
("h2", "", "Pape Gueye: ", "the goal"),
("p", "The Villarreal midfielder scored the only goal of the AFCON final, three minutes into extra time."),
("p", "That night wasn't the end of the story. When the penalty was given, Senegal's players and staff walked off in protest, and the final was held up until they came back. In March, CAF ruled that Senegal had forfeited the final and named Morocco champions. This week, the Court of Arbitration for Sport upheld Senegal's appeal and reinstated them as African champions."),
("h2", "", "Sadio Mané: ", "the captain"),
("p", "Mané captained Senegal, lifted the trophy in Rabat and was named Player of the Tournament. He knows this award well. He won it in 2019 and again in 2022, and a win in Lagos would make it three. He plays his club football for Al-Nassr in Saudi Arabia."),
("h2", "", "The rest of the ", "shortlists"),
("p", "Morocco and Senegal are all over the other men's categories too."),
("raw", "<ul>"
 "<li><strong>Goalkeeper of the Year:</strong> Yassine Bounou (Morocco, Al Hilal), Edouard Mendy (Senegal, Al Ahli), Vozinha (Cabo Verde, Colo-Colo)</li>"
 "<li><strong>Interclub Player of the Year:</strong> Teboho Mokoena (South Africa, Mamelodi Sundowns), Mohamed Rabie Hrimat (Morocco, AS FAR), Mahmoud Hassan &quot;Trezeguet&quot; (Egypt, Al Ahly)</li>"
 "<li><strong>Coach of the Year:</strong> Pape Thiaw (Senegal), Mohamed Ouahbi (Morocco), Pedro Leitão Brito &quot;Bubista&quot; (Cabo Verde)</li>"
 "<li><strong>Young Player of the Year:</strong> Yan Diomande (Côte d'Ivoire, Real Madrid), Ayoub Bouaddi (Morocco, Manchester City), Ibrahim Mbaye (Senegal, Aston Villa)</li>"
 "<li><strong>National Team of the Year:</strong> Senegal, Morocco, Cabo Verde</li>"
 "<li><strong>Club of the Year:</strong> Mamelodi Sundowns (South Africa), USM Alger (Algeria), AS FAR (Morocco)</li>"
 "</ul>"),
("h2", "", "When and ", "where"),
("p", "The CAF Awards take place on Wednesday, 2 December, at the Professor Wole Soyinka Centre for Culture and the Arts, Lagos's National Theatre. The ceremony starts at 7pm Lagos time, which is 9pm in Nairobi."),
("p", "Whoever's name is read out, January's final will be on that stage with them."),
("p", "<em>Photos: @wiwsport, @achrafhakimi, @brahim, @ismaelsaibari, @p.gueye24 and @sadiomaneofficiel on Instagram.</em>"),
]
